CommitDate: Tue Jun 9 13:21:22 2026 +0000

    Bug 1760272 - Keep invitation accept/decline buttons when the event is already in the calendar and another attendee replied. r=darktrojan


    When the event is already present in the calendar and another attendee replies (or the server otherwise re-syncs the event), the stored copy is re-stamped with a newer DTSTAMP while keeping the same SEQUENCE - a reply is not an organizer-side change per RFC 5545. The REQUEST handling in processFoundItems gated the accept/decline action on itip.compare() == 0, which also compares DTSTAMP, so the still-valid invitation looked "older" than the stored copy and was shown as "already processed" with only a Details button, even though the user's own PARTSTAT was still NEEDS-ACTION.

    Compare only the SEQUENCE so the buttons stay until the user's own PARTSTAT leaves NEEDS-ACTION or the organizer actually reschedules (higher SEQUENCE). As a side effect, a minor update (same SEQUENCE, newer DTSTAMP) received while the user is still unanswered now routes through REQUEST:NEEDS-ACTION instead of REQUEST:UPDATE-MINOR; this is safe because that path acts on the stored copy and preserves other attendees' synced status.

    Differential Revision: https://phabricator.services.mozilla.com/D305164

diff --git a/calendar/base/modules/utils/calItipUtils.sys.mjs b/calendar/base/modules/utils/calItipUtils.sys.mjs
index 6a7406a547a..fb373742ff2 100644
--- a/calendar/base/modules/utils/calItipUtils.sys.mjs
+++ b/calendar/base/modules/utils/calItipUtils.sys.mjs
@@ -1847,15 +1847,14 @@ ItipItemFinder.prototype = {
                     // again, fall back to using configured organizer if not found
                     let foundAttendee = firstFoundItem.getAttendeeById(att.id) || att;

-                    // If the user hasn't responded to the invitation yet and we
-                    // are viewing the current representation of the item, show the
-                    // accept/decline buttons. This means newer events will show the
-                    // "Update" button and older events will show the "already
-                    // processed" text.
+                    // If the user hasn't responded to the invitation yet and the
+                    // SEQUENCE is unchanged, show the accept/decline buttons. We
+                    // intentionally ignore the DTSTAMP here so a reply from another
+                    // attendee doesn't make the invitation look already processed.
                     if (
                       foundAttendee.participationStatus == "NEEDS-ACTION" &&
                       (item.calendar.getProperty("itip.disableRevisionChecks") ||
-                        itip.compare(itipItemItem, item) == 0)
+                        itip.compareSequence(itipItemItem, item) == 0)
                     ) {
                       actionMethod = "REQUEST:NEEDS-ACTION";
                       operations.push((opListener, partStat, extResponse) => {
diff --git a/calendar/test/browser/invitations/browser_imipBar.js b/calendar/test/browser/invitations/browser_imipBar.js
index 42dc1571d28..694422c19ce 100644
--- a/calendar/test/browser/invitations/browser_imipBar.js
+++ b/calendar/test/browser/invitations/browser_imipBar.js
@@ -197,3 +197,86 @@ add_task(async function testDeclineWithoutResponse() {
   await calendar.deleteItem(event);
   await BrowserTestUtils.closeWindow(win);
 });
+
+/**
+ * Tests that the accept/decline buttons are still shown when the event is
+ * already present in the calendar with a newer DTSTAMP (but the same SEQUENCE)
+ * and the user's own participation status is still NEEDS-ACTION. This is the
+ * state reached after another attendee replies and the server re-stamps the
+ * stored event: the invitation must not be treated as "already processed"
+ * (bug 1760272).
+ */
+add_task(async function testButtonsShownAfterOtherAttendeeReplied() {
+  transport.reset();
+
+  // Same UID and SEQUENCE as data/single-event.eml, but a newer DTSTAMP and our
+  // own PARTSTAT still NEEDS-ACTION, as if another attendee (Other) had just
+  // accepted and the server had re-written the stored copy.
+  const parser = Cc["@mozilla.org/calendar/ics-parser;1"].createInstance(Ci.calIIcsParser);
+  parser.parseString(
+    [
+      "BEGIN:VCALENDAR",
+      "VERSION:2.0",
+      "PRODID:-//Test//EN",
+      "BEGIN:VEVENT",
+      "UID:02e79b96",
+      "SEQUENCE:0",
+      "DTSTAMP:20220317T191602Z",
+      "DTSTART:20220316T110000Z",
+      "DTEND:20220316T113000Z",
+      "SUMMARY:Single Event",
+      "LOCATION:Somewhere",
+      "STATUS:CONFIRMED",
+      "ORGANIZER;CN=Sender:mailto:sender@example.com",
+      "ATTENDEE;CN=Sender;PARTSTAT=ACCEPTED;RSVP=FALSE:mailto:sender@example.com",
+      "ATTENDEE;CN=Receiver;PARTSTAT=NEEDS-ACTION;RSVP=TRUE:mailto:receiver@example.com",
+      "ATTENDEE;CN=Other;PARTSTAT=ACCEPTED;RSVP=TRUE:mailto:other@example.com",
+      "END:VEVENT",
+      "END:VCALENDAR",
+    ].join("\r\n")
+  );
+  const [storedEvent] = parser.getItems();
+  const addedEvent = await calendar.addItem(storedEvent);
+
+  let modifiedEvent;
+  const win = await openImipMessage(new FileUtils.File(getTestFilePath("data/single-event.eml")));
+  try {
+    const aboutMessage = win.document.getElementById("messageBrowser").contentWindow;
+
+    const acceptButton = aboutMessage.document.getElementById("imipAcceptButton");
+    await TestUtils.waitForCondition(
+      () => !acceptButton.hidden,
+      "accept button is shown even though the stored event has a newer DTSTAMP"
+    );
+
+    const declineButton = aboutMessage.document.getElementById("imipDeclineButton");
+    Assert.ok(!declineButton.hidden, "imipDeclineButton is shown");
+
+    // Accepting must act on the stored copy, not the (older) email: the user's
+    // own status becomes ACCEPTED while the other attendee's already-synced
+    // ACCEPTED status is preserved rather than reverted to the email's
+    // NEEDS-ACTION.
+    await clickAction(win, "imipAcceptButton");
+
+    // Wait for the acceptance to be written back to the stored event.
+    await TestUtils.waitForCondition(async () => {
+      const item = (await CalendarTestUtils.monthView.waitForItemAt(window, 3, 4, 1)).item;
+      return item.lastModifiedTime;
+    }, "the stored event has been modified");
+
+    modifiedEvent = (await CalendarTestUtils.monthView.waitForItemAt(window, 3, 4, 1)).item;
+    Assert.equal(
+      modifiedEvent.getAttendeeById("mailto:receiver@example.com").participationStatus,
+      "ACCEPTED",
+      "the user's own status is now ACCEPTED"
+    );
+    Assert.equal(
+      modifiedEvent.getAttendeeById("mailto:other@example.com").participationStatus,
+      "ACCEPTED",
+      "other attendee's synced ACCEPTED status is preserved (not taken from the email)"
+    );
+  } finally {
+    await calendar.deleteItem(modifiedEvent ?? addedEvent);
+    await BrowserTestUtils.closeWindow(win);
+  }
+});
